import React from 'react'
import {createRoot} from 'react-dom/client'
import {QueryClient, QueryClientProvider} from '@tanstack/react-query'
import {createRootRoute, createRouter, RouterProvider, createBrowserHistory} from '@tanstack/react-router'
import {JobsHeader} from '__SRC__/components/JobsHeader.tsx'
import {AuthProvider} from './Wallet.tsx'
import '__SRC__/styles.css'
const one = {id:'p1', name:'Hiring Agent', agent_id:'10401', address:'0x0000000000000000000000000000000000000001',state:'active',roles:['hire'],last_activity_at:null,revoke_json:'{}'}
const mode=new URLSearchParams(location.search).get('mode') ?? 'one'
const agents=mode==='none'?[]:mode==='many'?[one,{...one,id:'p2',name:'Second Publisher',agent_id:'10402',address:'0x0000000000000000000000000000000000000002'}]: mode==='blocked'?[{...one,roles:['work']},{...one,id:'unknown',name:'Unknown Agent',roles:undefined},{...one,id:'revoked',name:'Revoked Agent',state:'revoked'}]:[one]
window.__hiring={agents,fail:false,delay:20,reads:0,writes:[],copied:''}
const realFetch=window.fetch
window.fetch=async (url,init) => {
 if(!String(url).includes('/api/')) return realFetch(url,init)
 if(init?.method && init.method!=='GET') window.__hiring.writes.push(String(url))
 if(String(url).endsWith('/api/agents')) {
   window.__hiring.reads++
   await new Promise(r=>setTimeout(r,window.__hiring.delay))
   if(window.__hiring.fail) return new Response(JSON.stringify({ok:false,message:'Lookup failed'}),{status:503})
   return new Response(JSON.stringify({agents:window.__hiring.agents}))
 }
 return new Response(JSON.stringify({boards:[]}))
}
Object.defineProperty(navigator,'clipboard',{value:{writeText:async value=>{window.__hiring.copied=value}}})
const queryClient=new QueryClient({defaultOptions:{queries:{retry:false}}})
const route=createRootRoute({component:()=> <main className="mx-auto max-w-4xl p-6"><JobsHeader /></main>})
const router=createRouter({routeTree:route,history:createBrowserHistory()})
createRoot(document.getElementById('root')).render(<QueryClientProvider client={queryClient}><AuthProvider><RouterProvider router={router}/></AuthProvider></QueryClientProvider>)

