import {createContext,useContext,useState} from 'react'
const Context=createContext(null)
export function AuthProvider({children}) {
const [signedIn,set]=useState(new URLSearchParams(location.search).has('signedIn'))
return <Context.Provider value={{signedIn,address:'0x0000000000000000000000000000000000000009',signIn:async()=>set(true)}}>{children}</Context.Provider>
}
export const useAuth=()=>useContext(Context)
